const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Kandidat
  if (data.property_geburtsdatum) {
    let maxDistanz = 50;
    for (const key of Object.keys(data)) {
      if (key.toLowerCase().includes('distanz')) {
        const match = String(data[key]).match(/\d+/);
        if (match) maxDistanz = parseInt(match[0]);
        break;
      }
    }

    const lat = data.property_latitude;
    const lng = data.property_longitude;

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_wohnadresse,
        max_distanz_km: maxDistanz,
        lat: lat,
        lng: lng,
        has_coords: (lat !== null && lat !== undefined && lng !== null && lng !== undefined),
        type: 'kandidat'
      }
    });
  }
  // Fachgeschäft
  else if (data.property_adresse) {
    const lat = data.property_latitude;
    const lng = data.property_longitude;

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        lat: lat,
        lng: lng,
        has_coords: (lat !== null && lat !== undefined && lng !== null && lng !== undefined),
        type: 'shop'
      }
    });
  }
}

return results;

const items = $input.all();
const needGeocode = [];
const hasCoords = [];

for (const item of items) {
  if (!item.json.has_coords) {
    needGeocode.push(item);
  } else {
    hasCoords.push(item);
  }
}

return needGeocode;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const geo = items[i].json;
  const orig = $('Fehlende filtern').all()[i].json;

  if (geo.status === 'OK' && geo.results[0]) {
    const loc = geo.results[0].geometry.location;
    results.push({
      json: {
        ...orig,
        lat: loc.lat,
        lng: loc.lng,
        has_coords: true
      }
    });
  }
}

return results;

const items = $input.all();
const updatePromises = [];

for (const item of items) {
  const data = item.json;
  const payload = {
    properties: {
      Latitude: { number: data.lat },
      Longitude: { number: data.lng }
    }
  };

  updatePromises.push({
    json: {
      ...data,
      notion_payload: JSON.stringify(payload)
    }
  });
}

return updatePromises;

// Hole alle Items aus "Adressen extrahieren"
const allItems = $('Adressen extrahieren').all();
const geocodedIds = new Set();

// Markiere alle IDs die geocoded wurden
const geocoded = $input.all();
for (const item of geocoded) {
  geocodedIds.add(item.json.id);
}

// Erstelle finale Liste: geocoded items + items die schon coords hatten
const results = [];

for (const item of allItems) {
  const data = item.json;

  if (geocodedIds.has(data.id)) {
    // Nimm die geocoded version
    const geocodedItem = geocoded.find(g => g.json.id === data.id);
    if (geocodedItem) {
      results.push(geocodedItem);
    }
  } else if (data.has_coords) {
    // Hat schon Koordinaten, direkt nehmen
    results.push(item);
  }
}

return results;

const all = $input.all();
const kandidaten = all.filter(x => x.json.type === 'kandidat');
const shops = all.filter(x => x.json.type === 'shop');

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const results = [];

for (const k of kandidaten) {
  if (!k.json.lat || !k.json.lng) continue;

  const nearby = [];

  for (const s of shops) {
    if (!s.json.lat || !s.json.lng) continue;

    const d = distance(k.json.lat, k.json.lng, s.json.lat, s.json.lng);
    if (d <= k.json.max_distanz_km) {
      nearby.push({ id: s.json.id, name: s.json.name, dist: Math.round(d*10)/10 });
    }
  }

  nearby.sort((a,b) => a.dist - b.dist);

  if (nearby.length > 0) {
    const text = nearby.map((x,i) => `${i+1}. ${x.name}: ${x.dist} km`).join('\n');

    results.push({
      json: {
        kandidat_id: k.json.id,
        shop_ids: nearby.map(x => x.id),
        min_dist: nearby[0].dist,
        comment: 'Zugeordnete Geschäfte:\n' + text
      }
    });
  }
}

return results;
